// Turn the ingest's stdout into fields the rest of the workflow can branch on.
//
// The exit code is read from the EXITCODE= line the wrapper prints, not from
// the node's own exitCode: n8n discards stdout when a command exits non-zero,
// which is exactly the case we most need the output for.

const r = $input.first().json;
const out = `${r.stdout || ''}\n${r.stderr || ''}`.trim();
const lines = out.split('\n').map(l => l.trim());

const codeLine = out.match(/EXITCODE=(\d+)/);
const exitCode = codeLine ? Number(codeLine[1]) : Number(r.exitCode ?? 1);

const summary = out.match(/(\d+) succeeded · (\d+) failed · (\d+)s/);

// A ✓/✗ line in the summary block always carries the store id, e.g.
//   ✗   2 Brooklinen           2026-08-04  FAILED — file not found
// Requiring that id is what keeps preflight errors — which also start with ✗,
// but are about credentials rather than a store — out of the failed list.
const storeLines = lines.filter(l => /^[✓✗]\s+\d+\s/.test(l));
const failedStores = storeLines.filter(l => l.startsWith('✗'));
const blocker = lines.find(l => l.startsWith('✗') && !/^✗\s+\d+\s/.test(l)) || null;

const idle = /nothing to do|0 to ingest/.test(out);

let text;
if (summary) {
  text = `Shopify ingest: ${summary[1]} succeeded, ${summary[2]} failed in ${summary[3]}s`;
} else if (idle) {
  text = 'Nothing new on Drive — every store and date is already ingested';
} else if (blocker) {
  text = `Shopify ingest never started — ${blocker.replace(/^✗\s*/, '')}`;
} else {
  text = `Shopify ingest exited ${exitCode} without a summary — check the log`;
}

return [{
  json: {
    ok: exitCode === 0,
    idle,
    exitCode,
    succeeded: summary ? Number(summary[1]) : 0,
    failed: summary ? Number(summary[2]) : failedStores.length,
    seconds: summary ? Number(summary[3]) : null,
    stores: storeLines,
    failedStores,
    blocker,
    text,
    log: out.slice(-4000),
  },
}];
